  line-height: 1.6;
}

main {
  color: #334155;
}

header,
footer {
  background-color: #e2e8f0;
  color: #0f172a;
}

p {
  color: #475569;
}

.intro {
  color: #0f766e;
}

nav a {
  font-weight: 600;
  text-decoration: none;
}

main h2 {
  color: #0f766e;
}

nav a {
  color: #0f172a;
}

nav a {
  color: #0f766e;
}

header p {
  color: #475569;
}

.intro {
  font-weight: 700;
}

main {
  padding: 1.5rem;
}

section {
  border: 1px solid #cbd5e1;
}

footer {
  margin-top: 2rem;
}

header {
  padding: 1rem 1.5rem;
}

nav a {
  margin-right: 1rem;
}

