  main {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (min-width: 64rem) {
  main > :first-child {
    grid-column: span 2;
  }
}

:root {
  --color-accent: #1d4ed8;
  --color-accent-strong: #1e40af;
  --space-section: 1.5rem;
}

a {
  color: var(--color-accent);
}

main {
  gap: var(--space-section);
}

